package com.citacloud.app.services;
import com.citacloud.app.models.ConfiguracionEmpresaFase2;
import com.citacloud.app.repositories.ConfiguracionEmpresaFase2Repository;
import org.springframework.stereotype.Service;
import java.util.UUID;
@Service public class ConfiguracionFase2Service { private final ConfiguracionEmpresaFase2Repository repo; public ConfiguracionFase2Service(ConfiguracionEmpresaFase2Repository r){repo=r;} public ConfiguracionEmpresaFase2 obtener(UUID empresa){return repo.findById(empresa).orElseGet(()->{ConfiguracionEmpresaFase2 c=new ConfiguracionEmpresaFase2();c.setEmpresaId(empresa);return c;});} public ConfiguracionEmpresaFase2 guardar(UUID e,boolean requiere,String prefijo,int siguiente,boolean recordatorios){return guardar(e,requiere,prefijo,siguiente,recordatorios,true,"METROS","KG","C");} public ConfiguracionEmpresaFase2 guardar(UUID e,boolean requiere,String prefijo,int siguiente,boolean recordatorios,String altura,String peso,String temperatura){return guardar(e,requiere,prefijo,siguiente,recordatorios,true,altura,peso,temperatura);} public ConfiguracionEmpresaFase2 guardar(UUID e,boolean requiere,String prefijo,int siguiente,boolean recordatorios,boolean notificaciones,String altura,String peso,String temperatura){if(e==null)throw new IllegalArgumentException("No se pudo identificar la empresa.");ConfiguracionEmpresaFase2 c=obtener(e);c.setRequiereAprobacionCitas(requiere);c.setPrefijoFactura(prefijo==null||prefijo.isBlank()?"FAC":prefijo.trim().toUpperCase());c.setSiguienteFactura(Math.max(1,siguiente));c.setRecordatoriosActivos(recordatorios);c.setNotificacionesActivas(notificaciones);c.setUnidadAltura("PIES".equals(altura)?"PIES":"METROS");c.setUnidadPeso("LIBRAS".equals(peso)?"LIBRAS":"KG");c.setUnidadTemperatura("F".equals(temperatura)?"F":"C");return repo.save(c);} }
